<template><span class="ui-notification-dot"><slot/><i v-if="count!==0" :class="{'is-dot':dot}" :aria-label="dot?'有新通知':`${count} 条通知`">{{ dot?'':display }}</i></span></template>
<script setup lang="ts">import{computed}from'vue';const props=withDefaults(defineProps<{count?:number;max?:number;dot?:boolean}>(),{count:0,max:99});const display=computed(()=>props.count>props.max?`${props.max}+`:String(props.count));</script>
<style scoped>.ui-notification-dot{position:relative;display:inline-flex}.ui-notification-dot>i{position:absolute;top:-6px;right:-8px;display:grid;min-width:16px;height:16px;place-items:center;padding:0 4px;border:2px solid var(--ui-surface);border-radius:9px;color:#fff;background:var(--ui-danger);font-size:9px;font-style:normal}.ui-notification-dot>i.is-dot{top:-2px;right:-2px;min-width:8px;width:8px;height:8px;padding:0}</style>
